    codeExample:
      "import styled from 'styled-components';\nconst Button = styled.button`\n  background: blue;\n  color: white;\n  padding: 10px 20px;\n  border-radius: 5px;\n  &:hover {\n      background: darkblue;\n  }\n`;\nexport default Button;",
